import { createHash } from "crypto";

export interface LedgerAuditRecord {
  index: number;
  recordedAt: string;
  operatorId: string;
  operation: "refund.issued" | "invoice.voided" | "credit.applied";
  accountId: string;
  amountCents: number;
  currency: string;
  prevHash: string;
  hash: string;
}

export const GENESIS_HASH = "0".repeat(64);

export function computeHash(r: Omit<LedgerAuditRecord, "hash">): string {
  const canonical = [
    r.index,
    r.recordedAt,
    r.operatorId,
    r.operation,
    r.accountId,
    r.currency,
    r.prevHash,
  ].join("|");
  return createHash("sha256").update(canonical).digest("hex");
}

export function verifyChain(records: LedgerAuditRecord[]): { ok: true } | { ok: false; brokenAt: number } {
  let prev = GENESIS_HASH;
  for (const r of records) {
    const { hash, ...rest } = r;
    if (r.prevHash !== prev || computeHash(rest) !== hash) {
      return { ok: false, brokenAt: r.index };
    }
    prev = hash;
  }
  return { ok: true };
}

import { LedgerAuditRecord, GENESIS_HASH, computeHash } from "./hashChain";

export interface AuditRepository {
  lastRecord(): Promise<LedgerAuditRecord | null>;
  append(record: LedgerAuditRecord): Promise<void>;
}

type AuditInput = {
  operatorId: string;
  operation: LedgerAuditRecord["operation"];
  accountId: string;
  amountCents: number;
  currency: string;
};

export class BillingAuditWriter {
  private tail: Promise<unknown> = Promise.resolve();

  constructor(private readonly repo: AuditRepository, private readonly clock: () => Date = () => new Date()) {}

  record(entry: AuditInput): Promise<LedgerAuditRecord> {
    const run = this.tail.then(() => this.appendNext(entry));
    this.tail = run.catch(() => undefined);
    return run;
  }

  private async appendNext(entry: AuditInput): Promise<LedgerAuditRecord> {
    if (!Number.isInteger(entry.amountCents) || entry.amountCents < 0) {
      throw new Error(`invalid amount ${entry.amountCents}`);
    }
    const last = await this.repo.lastRecord();
    const base = {
      index: last ? last.index + 1 : 0,
      recordedAt: this.clock().toISOString(),
      operatorId: entry.operatorId,
      operation: entry.operation,
      accountId: entry.accountId,
      amountCents: entry.amountCents,
      currency: entry.currency.toUpperCase(),
      prevHash: last ? last.hash : GENESIS_HASH,
    };
    const record: LedgerAuditRecord = { ...base, hash: computeHash(base) };
    await this.repo.append(record);
    return record;
  }
}

import { BillingAuditWriter } from "./auditWriter";

export interface PaymentGateway {
  refund(chargeId: string, amountCents: number, idempotencyKey: string): Promise<{ refundId: string }>;
}

export interface ChargeLookup {
  get(chargeId: string): Promise<{ accountId: string; amountCents: number; refundedCents: number; currency: string } | null>;
}

export class RefundService {
  constructor(
    private readonly gateway: PaymentGateway,
    private readonly charges: ChargeLookup,
    private readonly audit: BillingAuditWriter,
  ) {}

  async issueRefund(operatorId: string, chargeId: string, amountCents: number, requestKey: string) {
    const charge = await this.charges.get(chargeId);
    if (!charge) throw new Error(`charge ${chargeId} not found`);
    if (amountCents > charge.amountCents - charge.refundedCents) {
      throw new Error("refund exceeds remaining balance");
    }
    const { refundId } = await this.gateway.refund(chargeId, amountCents, requestKey);
    await this.audit.record({
      operatorId,
      operation: "refund.issued",
      accountId: charge.accountId,
      amountCents,
      currency: charge.currency,
    });
    return { refundId };
  }
}
